-- FIT90 potential-member import. It is safe to retry because each source lead has a LegacyLeadId marker.
SET NAMES utf8mb4;
START TRANSACTION;
DROP TEMPORARY TABLE IF EXISTS `tmp_fit90_lead_import`;
CREATE TEMPORARY TABLE `tmp_fit90_lead_import` (
  `external_id` VARCHAR(50) NOT NULL,
  `name` VARCHAR(200) NOT NULL,
  `phone` VARCHAR(30) NULL,
  `email` VARCHAR(120) NULL,
  `gender` VARCHAR(10) NULL,
  `notes` TEXT NULL,
  `follow_up_at` VARCHAR(20) NULL,
  `created_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

























































SELECT t.`name`, t.`phone`, t.`email`, t.`gender`, 1, 'new', t.`notes`, t.`follow_up_at`, 0, COALESCE(t.`created_at`, NOW()), NOW()
FROM `tmp_fit90_lead_import` t
WHERE NOT EXISTS (
  SELECT 1 FROM `club_leads` existing
  WHERE existing.`branch_id` = 1
    AND LOCATE(
      CONVERT(CONCAT(_utf8mb4'LegacyLeadId: ', t.`external_id`) USING utf8mb4) COLLATE utf8mb4_unicode_ci,
      CONVERT(existing.`notes` USING utf8mb4) COLLATE utf8mb4_unicode_ci
    ) > 0
);

COMMIT;
SELECT COUNT(*) AS imported_leads FROM `club_leads` WHERE `branch_id` = 1 AND `notes` LIKE '%LegacyLeadId:%';
